item.aggregated_output:
name: CI

on:
  merge_group:
    types: [checks_requested]
  push:
    branches: [main]
  pull_request:
  schedule:
    - cron: "0 6 * * 1" # Preserve the former weekly full-health Rust run.
  workflow_dispatch:
    inputs:
      diagnostic_timing:
        description: Full-workspace test-only delivery phase timings
        type: boolean
        default: false

concurrency:
  group: ci-${{ github.event_name }}-${{ github.event.pull_request.number || github.ref }}-${{ github.event_name == 'push' && github.run_id || 'candidate' }}
  cancel-in-progress: ${{ github.event_name == 'pull_request' || github.event_name == 'merge_group' }}

# Read-only: every job just checks out and runs tooling — nothing writes back.
permissions:
  contents: read

env:
  CARGO_TERM_COLOR: always
  # Keep stack file/line diagnostics without generating type/variable debug data.
  CARGO_PROFILE_DEV_DEBUG: line-tables-only
  CARGO_PROFILE_TEST_DEBUG: line-tables-only
  MESH_TALK_TEST_TIMING: ${{ inputs.diagnostic_timing && '1' || '0' }}

jobs:
  scope:
    uses: ./.github/workflows/ci-scope.yml

  checks:
    name: checks (ubuntu-latest)
    if: ${{ !cancelled() }}
    needs: [scope]
    runs-on: ubuntu-latest
    timeout-minutes: 90
    steps:
      - uses: actions/checkout@3d3c42e5aac5ba805825da76410c181273ba90b1 # v7.0.1
        with:
          fetch-depth: 2
      - id: scope
        uses: ./.github/actions/ci-scope
        with:
          full: ${{ needs.scope.outputs.full }}
          upstream_result: ${{ needs.scope.result }}
      - name: Report documentation-only coverage through Codecov
        if: steps.scope.outputs.full == 'false'
        uses: codecov/codecov-action@303a32d7a59b442fa8d48b6a1cc6825c09c847a5 # v7.1.1
        with:
          version: v11.3.2
          run_command: empty-upload
          token: ${{ secrets.CODECOV_TOKEN }}
          fail_ci_if_error: true
      - uses: actions/setup-node@949feb2413d6458794dcd2491c4babbbce0c15c1 # v7.1.0
        if: ${{ steps.scope.outputs.full == 'true' }}
        with:
          node-version: 22
          cache: npm
          cache-dependency-path: frontend/package-lock.json

      - name: Prepare hosted Linux build storage
        if: ${{ steps.scope.outputs.full == 'true' && (runner.os == 'Linux') }}
        id: runner_storage
        shell: bash
        run: sudo --preserve-env=GITHUB_ACTIONS,RUNNER_ENVIRONMENT,RUNNER_OS "$(command -v node)" scripts/ci/runner-storage.mjs --prepare | tee "$RUNNER_TEMP/runner-storage.json"

      - name: Preserve runner storage measurements
        if: ${{ steps.scope.outputs.full == 'true' && (always() && steps.runner_storage.outcome == 'success') }}
        continue-on-error: true
        uses: actions/upload-artifact@v7
        with:
          name: runner-storage-${{ github.job }}-${{ strategy.job-index || 0 }}-${{ github.run_attempt }}
          path: ${{ runner.temp }}/runner-storage.json
          if-no-files-found: error
          retention-days: 14

      - name: Prepare Ubuntu archive source
        if: ${{ steps.scope.outputs.full == 'true' && (runner.os == 'Linux') }}
        shell: bash
        run: sudo --preserve-env=GITHUB_ACTIONS,RUNNER_ENVIRONMENT,RUNNER_OS "$(command -v node)" scripts/ci/ubuntu-apt-source.mjs

      # Tauri v2 system libraries (Linux only).
      - name: Install Tauri system dependencies (Linux)
        if: ${{ steps.scope.outputs.full == 'true' }}
        run: |
          sudo apt-get update
          sudo apt-get install -y \
            libwebkit2gtk-4.1-dev \
            libgtk-3-dev \
            libayatana-appindicator3-dev \
            librsvg2-dev \
            patchelf \
            gdb

      - name: Install Rust toolchain
        if: ${{ steps.scope.outputs.full == 'true' }}
        uses: dtolnay/rust-toolchain@stable
        with:
          components: clippy, rustfmt, llvm-tools-preview

      - name: Cache Rust build
        if: ${{ steps.scope.outputs.full == 'true' }}
        uses: Swatinem/rust-cache@v2
        with:
          save-if: ${{ github.ref == 'refs/heads/main' }}
          workspaces: . -> target
          shared-key: workspace-checks-checks
          cache-on-failure: true

      - name: Install frontend dependencies
        if: ${{ steps.scope.outputs.full == 'true' }}
        shell: bash
        run: |
          npm ci --prefix frontend

      - name: Install cargo-llvm-cov and cargo-nextest
        if: ${{ steps.scope.outputs.full == 'true' }}
        uses: taiki-e/install-action@v2.88.1
        with:
          tool: cargo-llvm-cov@0.8.7,cargo-nextest@0.9.150

      - name: Verify coverage accumulation with the actual tool
        if: ${{ steps.scope.outputs.full == 'true' }}
        # These fixtures launch real Cargo/rustc processes and share this job's
        # package cache. Give each compiler contract exclusive execution.
        run: node --test --test-concurrency=1 scripts/ci/backend-coverage.test.mjs scripts/ci/native-host-coverage.test.mjs scripts/ci/rust-profile.test.mjs scripts/ci/linux-crash-diagnostics.test.mjs

      - name: Prepare and verify Linux native crash evidence
        if: ${{ steps.scope.outputs.full == 'true' && (runner.os == 'Linux') }}
        shell: bash
        run: |
          set -e -o pipefail
          ulimit -c 262144
          node scripts/ci/linux-crash-diagnostics.mjs setup
          node scripts/ci/linux-crash-diagnostics.mjs selftest

      # Tauri reads frontendDist, so build the frontend before any Cargo step.
      - name: Build frontend
        if: ${{ steps.scope.outputs.full == 'true' }}
        working-directory: frontend
        run: npm run build

      - name: Check built JavaScript for macOS 12 WKWebView
        if: ${{ steps.scope.outputs.full == 'true' }}
        working-directory: frontend
        run: npm run check:build-syntax

      # Keep native lint, production builds and complete tests on every OS.
      - name: Clippy
#!/usr/bin/env node
// One compiled archive, eight serial ASan partitions and exact union evidence.
import assert from "node:assert/strict";
import { createHash } from "node:crypto";
import { createReadStream, existsSync, mkdirSync, mkdtempSync, readFileSync, readdirSync, rmSync, writeFileSync, appendFileSync } from "node:fs";
import os from "node:os";
import path from "node:path";
import { fileURLToPath } from "node:url";
import { command as runLogged, inventory, verifyPartition, verifyExecution, versions } from "./windows-coverage.mjs";

const partitions = [1, 2, 3, 4, 5, 6, 7, 8];
// Fixed measured outliers, not a timing database. Names must remain exact and
// default runnable in the full archive inventory before sealing or execution.
export const reservedCohorts = Object.freeze([
  Object.freeze(["node::account_documents::tests::group_inventory_long_canonical_names_fit_payload_budget_and_preserve_required_members"]),
  Object.freeze([
    "node::account_documents::tests::inventory_causality::group_inventory_directory_known_unavailable_source_can_be_acknowledged_by_another_source",
    "node::account_documents::tests::group_control_unavailable_obsolete_cache_cannot_orphan_a_large_negative_head",
    "node::account_documents::tests::group_control_normal_authorization_history_growth_keeps_bounded_current_heads",
  ]),
]);
const exactTests = names => names.map(name => `test(=${name})`).join(" or ");
export function verifyReservedInventory(full) {
  for (const name of reservedCohorts.flat()) {
    const matches = full.filter(row => row.eventName.slice(row.eventName.indexOf("$") + 1) === name);
    assert.equal(matches.length, 1, `ASan reserved test missing or ambiguous: ${name}`);
    assert.ok(matches[0].selected && !matches[0].ignored, `ASan reserved test is not default runnable: ${name}`);
  }
}
const target = "x86_64-unknown-linux-gnu";
const config = ".config/nextest-asan.toml";
const hash = value => createHash("sha256").update(value).digest("hex");
const read = file => JSON.parse(readFileSync(file, "utf8"));
const write = (file, value) => writeFileSync(file, `${JSON.stringify(value, null, 2)}\n`);
const digest = value => hash(JSON.stringify(value));

export function nightlyFromManifest(text) {
  const header = text.split(/^\[/mu)[0];
  const dates = [...header.matchAll(/^date\s*=\s*"(\d{4}-\d{2}-\d{2})"\s*$/gmu)];
  assert.equal(dates.length, 1, "Installed nightly manifest date is missing or ambiguous");
  const date = dates[0][1];
  const instant = new Date(`${date}T00:00:00Z`);
  assert.ok(Number.isFinite(instant.getTime()), "Invalid nightly manifest date");
  assert.equal(instant.toISOString().slice(0, 10), date, "Invalid nightly manifest date");
  return `nightly-${date}`;
}

export function partitionArgs(mode, buildArgs, shard) {
  assert.ok(["list", "run"].includes(mode), "Invalid ASan command mode");
  assert.ok(shard === undefined || partitions.includes(shard), "Invalid ASan partition");
  return ["nextest", mode, ...buildArgs, "--config-file", path.resolve(config), "--user-config-file", "none", "--profile", "default", ...(shard === undefined ? [] : shard <= 6 ? ["--partition", `hash:${shard}/6`, "-E", `not (${exactTests(reservedCohorts.flat())})`] : ["-E", `(${exactTests(reservedCohorts[shard - 7])})`]), ...(mode === "list" ? ["--message-format", "json"] : ["--test-threads", "1", "--retries", "0", "--no-fail-fast", "--no-tests", "fail", "--message-format", "libtest-json-plus", "--message-format-version", "0.1"])];
}

export function verifyAsanUnion(bundles, expected) {
  assert.equal(bundles.length, partitions.length, "Expected exactly eight ASan partitions");
  assert.deepEqual(bundles.map(bundle => bundle.receipt.shard).sort(), partitions, "Duplicate or missing ASan partition");
  const full = bundles[0].full;
  verifyReservedInventory(full);
  for (const bundle of bundles) {
    const { receipt, selected, execution } = bundle;
    assert.equal(receipt.schema, 1, "Unsupported ASan receipt");
    assert.deepEqual(receipt.identity, expected, "ASan source/run/toolchain/config identity mismatch");
    assert.deepEqual(bundle.full, full, "ASan full inventory differs across runners");
    assert.equal(digest(bundle.full), receipt.fullSha256, "ASan full inventory digest mismatch");
    assert.equal(digest(selected), receipt.selectedSha256, "ASan selected inventory digest mismatch");
    assert.equal(hash(execution), receipt.executionSha256, "ASan execution digest mismatch");
  }
  verifyPartition(full, bundles.map(bundle => bundle.selected), partitions.length);
  let executedTests = 0;
  for (const { receipt, selected, execution } of bundles) {
    verifyExecution(execution, selected);
    const count = selected.filter(row => row.selected).length;
    assert.equal(receipt.executedTests, count, "ASan execution count mismatch");
    executedTests += count;
  }
  return { totalTests: full.length, executedTests, ignoredTests: full.filter(row => row.ignored).length, shards: partitions.length };
}

// Exported for the real stable-toolchain protocol fixture. Hosted CLI callers use
// the sealed producer archive and verified runtime identity below, never test flags.
export async function runPartition(shard, directory, { buildArgs, identity, expectedInventory, cargoPrefix = [], env = process.env, afterExecution = async () => {} } = {}) {
