    steps:
      - name: Checkout
        uses: actions/checkout@3d3c42e5aac5ba805825da76410c181273ba90b1 # v7.0.1
      - name: Setup Node.js
        uses: actions/setup-node@v7.1.0
        with:
          node-version: 22
          cache: npm
          cache-dependency-path: frontend/package-lock.json
      - name: Reserve browser cleanup and evidence time
        shell: bash
        env:
          UI_JOB_MINUTES: ${{ inputs.timeout_minutes }}
        run: |
          node --input-type=module <<'JS'
          import { appendFileSync, mkdirSync, writeFileSync } from "node:fs";
          const minutes = Number(process.env.UI_JOB_MINUTES);
          if (!Number.isFinite(minutes) || minutes <= 2) throw Error("Invalid browser job budget");
          const startedAt = Date.now();
          const deadline = startedAt + (minutes - 2) * 60000;
          mkdirSync("ui-runner-evidence", { recursive: true });
          writeFileSync("ui-runner-evidence/budget.json", JSON.stringify({ startedAt, deadline, jobMinutes: minutes, reserveMinutes: 2 }));
