          JS
      - name: Validate full-suite partition layout
        run: node ../scripts/evals/chromium-evidence.mjs layout
        env:
          CHROMIUM_OS: ${{ matrix.os }}
          CHROMIUM_SHARDS: ${{ inputs.shards }}
          CHROMIUM_TOTAL: ${{ inputs.shard_total }}
          CHROMIUM_SHARD: ${{ matrix.shard }}
      - name: Install dependencies
        run: npm ci
      - name: Prepare Ubuntu archive source
        if: runner.os == 'Linux'
        shell: bash
        run: sudo --preserve-env=GITHUB_ACTIONS,RUNNER_ENVIRONMENT,RUNNER_OS "$(command -v node)" ../scripts/ci/ubuntu-apt-source.mjs
      - name: Install Playwright browser
        run: npx playwright install --with-deps chromium
      # Fresh browser contexts repeatedly load Vite's module graph. Windows'
      # default 16K outbound ports can exhaust before TIME_WAIT sockets expire,
      # leaving unrelated tests with ERR_NO_BUFFER_SPACE and a blank login page.
      # Keep the server's port 5173 outside this disposable runner's client pool.
      - name: Reserve Windows browser connection capacity
        if: runner.os == 'Windows'
        shell: pwsh
        run: |
          netsh int ipv4 set dynamicport tcp start=10000 num=55535
          if ($LASTEXITCODE -ne 0) { throw "Failed to expand the Windows TCP client port range" }
