      # tests across machines rather than competing with Vite on one runner.
      - name: Run UI E2E
        id: ui
        run: node ../scripts/ci/ui-runner.mjs --workers=1 --retries=0 --shard=${{ matrix.shard }}/${{ inputs.shard_total }} --reporter=list,blob,json,../scripts/ci/ui-runner.mjs
        env:
          PLAYWRIGHT_JSON_OUTPUT_NAME: full-results.json
          EVAL_SOURCE_SHA: ${{ github.sha }}
          MESH_TALK_E2E_COVERAGE: ${{ runner.os == 'Linux' && '1' || '0' }}
      - name: Validate portable evidence from this full-suite shard
        run: node ../scripts/evals/chromium-evidence.mjs extract full-results.json eval-results/chromium-shard
        env:
          CHROMIUM_SHARD: ${{ matrix.shard }}
      - name: Upload portable shard evidence
        uses: actions/upload-artifact@v7
        with:
