          path: frontend/eval-results/chromium-shard/
          compression-level: 0
          if-no-files-found: error
          retention-days: 14
      - name: Diagnose Windows browser connection failures
        if: failure() && runner.os == 'Windows'
        shell: pwsh
        run: |
          netsh int ipv4 show dynamicport tcp
