          writeFileSync("coverage/shard.json", JSON.stringify({ sourceSha: process.env.SOURCE_SHA, shard: Number(process.env.SHARD), total: 4 }));'
        env:
          SOURCE_SHA: ${{ github.sha }}
          SHARD: ${{ matrix.shard }}
      - name: Upload Linux coverage parts
"}}

